   const entry=Object.entries(window.PORTAL_CARRIER_LOGOS||{}).find(([name])=>normalize(name)===(aliases[key]||key));if(!entry)return;
   const [name,logo]=entry,img=document.createElement('img'),fallback=box.querySelector('span');img.alt=name+' logo';img.decoding='async';img.hidden=true;
   img.onload=()=>{img.hidden=false;fallback.hidden=true;box.classList.toggle('bob-policy-logo-dark',!!logo.dark);};
