 function csvRows(rows){const columns=[['Client ID','profile_id'],['Policy ID','id'],['Client name','client_name'],['Closing agent name','agent_name'],['Phone','phone'],['Alternate phone','alternate_phone'],['Email','email'],['Address','address_line1'],['Address line 2','address_line2'],['City','city'],['State','state'],['ZIP','zip'],['Date of birth','date_of_birth'],['Mortgage balance','mortgage_balance'],['Carrier','carrier'],['Policy type','policy_type'],['Monthly premium','monthly_payment'],['Policy number','policy_number'],['Application date','application_date'],['Policy effective date','effective_date'],['Agent pipeline stage','pipeline_stage'],['Agent-reported production status','status'],['Carrier status','carrier_status'],['Carrier confirmation matches policy','carrier_status_current'],['Carrier confirmed on','carrier_confirmed_on'],['Carrier confirmation source','carrier_status_source'],['Carrier reference','carrier_status_reference'],['Carrier status recorded by','carrier_status_recorded_by_name'],['Carrier status recorded at','carrier_status_recorded_at'],['Confirmed carrier','carrier_status_carrier'],['Confirmed policy type','carrier_status_policy_type'],['Confirmed policy number','carrier_status_policy_number'],['Comp percent','comp_percent'],['Advance percent','advance_percent'],['Estimated advance','estimated_advance'],['Next follow-up','next_task_due'],['Notes','notes']];return [columns.map(([h])=>csvCell(h)).join(','),...rows.map(r=>columns.map(([,key])=>csvCell(key==='pipeline_stage'?stageLabel(r[key]):key==='carrier_status'?(carrierRecheck(r)?'Needs recheck (previous: '+carrierLabel(r[key])+')':carrierLabel(r[key])):r[key])).join(','))].join('\r\n');}
