 function compAgents(){const rows=B.grid?.agents||[];return rows.some(a=>a.id===S.profile.id)?rows:[{id:S.profile.id,full_name:S.profile.full_name||'My rates'},...rows];}
 function compAgent(){return B.compAgent||S.profile.id;}
 function compGroups(){
  const groups=carriers.map(carrier=>({carrier,category:productCatalog.find(c=>c.carrier===carrier)?.category||'Additional carrier',products:(productCatalog.find(c=>c.carrier===carrier)?.products||[]).map(p=>({name:p[0],detail:p[1]||'',kind:p[2]||'life',value:productName(p),rates:[]}))}));
  for(const rate of B.grid?.rows||[]){
   if(rate.agent_id!==compAgent())continue;
   let group=groups.find(c=>compKey(c.carrier)===compKey(rate.carrier));if(!group){group={carrier:rate.carrier,category:'Saved carrier',products:[]};groups.push(group);}
   let product=group.products.find(p=>compKey(p.value)===compKey(rate.policy_type));if(!product){product={name:rate.policy_type,detail:'Saved product',value:rate.policy_type,rates:[]};group.products.push(product);}
   product.rates.push(rate);
  }
  for(const group of groups)for(const p of group.products)p.rates.sort((a,b)=>String(b.effective_date).localeCompare(String(a.effective_date)));
  return groups.sort((a,b)=>Number(!a.products.length)-Number(!b.products.length)||a.carrier.localeCompare(b.carrier));
 }
 function compResults(){
  const query=B.compSearch.trim().toLowerCase(),today=localDate(),master=S.profile.is_super_admin;
  const groups=compGroups().map(g=>({...g,products:g.products.filter(p=>(!B.compOnlySet||p.rates.length)&&(!query||[g.carrier,g.category,p.value].join(' ').toLowerCase().includes(query)))})).filter(g=>g.products.length||(!B.compOnlySet&&!query&&!productCatalog.some(c=>c.carrier===g.carrier)));
  if(!groups.length)return '<div class="bob-comp-empty"><h3>No matching products</h3><p>Try another carrier or product name, or turn off “Configured only”.</p></div>';
  return groups.map(g=>'<section class="bob-comp-carrier"><header><div class="bob-policy-logo" data-bob-carrier-logo="'+esc(g.carrier)+'"><span aria-hidden="true">'+esc(initials(g.carrier))+'</span></div><span class="bob-comp-product-count">'+g.products.length+' '+(g.products.length===1?'product':'products')+'</span></header><div class="bob-comp-carrier-title"><h3>'+esc(g.carrier)+'</h3><p>'+esc(g.category)+'</p></div>'+(g.products.length?'<div class="bob-comp-table-wrap"><table class="bob-comp-table"><thead><tr><th>Product</th><th>Comp</th><th>Advance</th><th>Effective</th>'+(master?'<th><span class="sr-only">Actions</span></th>':'')+'</tr></thead><tbody>'+g.products.map(p=>{
   const current=p.rates.find(r=>r.effective_date<=today),future=p.rates.filter(r=>r.effective_date>today),history=p.rates.length?'<details class="bob-comp-history"><summary>'+p.rates.length+' saved '+(p.rates.length===1?'rate':'rates')+'</summary><ul>'+p.rates.map(r=>'<li><span>'+dateText(r.effective_date)+(r.effective_date>today?' · Scheduled':'')+'</span><strong>'+esc(r.comp_percent)+'% comp · '+esc(r.advance_percent)+'% advance</strong></li>').join('')+'</ul></details>':'';
   return '<tr><td><strong>'+esc(p.name)+'</strong>'+(p.detail?'<small>'+esc(p.detail)+'</small>':'')+(p.kind==='annuity'?'<small class="bob-comp-annuity-label">Annuity · rate only</small>':'')+history+'</td><td class="bob-comp-percent '+(!current?'is-unset':'')+'">'+(current?esc(current.comp_percent)+'%':'—')+'</td><td class="bob-comp-advance">'+(current?esc(current.advance_percent)+'%':'—')+'</td><td class="bob-comp-effective">'+(current?dateText(current.effective_date):'<span class="bob-comp-unset">'+(future.length?'Scheduled':'Not set')+'</span>')+(current&&future.length?'<small>+'+future.length+' scheduled</small>':'')+'</td>'+(master?'<td><button class="bob-comp-rate-button" data-comp-carrier="'+esc(g.carrier)+'" data-comp-product="'+esc(p.value)+'" aria-label="Set rate for '+esc(g.carrier+' '+p.value)+'">'+(p.rates.length?'Set rate':'+ Set')+'</button></td>':'')+'</tr>';
  }).join('')+'</tbody></table></div>':'<div class="bob-comp-no-products"><p>No product list added for this carrier yet.</p>'+(master?'<button class="bob-link" data-comp-carrier="'+esc(g.carrier)+'" data-comp-product="">+ Add a product rate</button>':'')+'</div>')+'</section>').join('');
 }
 function gridPage(){
  const groups=compGroups(),count=groups.reduce((n,g)=>n+g.products.length,0),configured=groups.reduce((n,g)=>n+g.products.filter(p=>p.rates.length).length,0),master=S.profile.is_super_admin,agents=compAgents();
  return '<section class="bob-comp-workspace"><header class="bob-comp-heading"><div><p class="bob-comp-eyebrow">COMPENSATION</p><h2>Carrier & product rates</h2><p>One place to manage each agent’s compensation by carrier and product.</p></div>'+(master?'<div class="bob-comp-heading-actions"><button class="btn primary" id="bobAddRate">+ Add rate</button><button class="bob-link" id="bobResetPin">Reset selected PIN</button></div>':'<span class="bob-comp-readonly">View only · rates managed by Peter</span>')+'</header><div class="bob-comp-toolbar"><label class="bob-field"><span>'+(master?'Rates for':'Viewing rates for')+'</span><select id="bobCompAgent" aria-label="Compensation agent">'+agents.map(a=>'<option value="'+esc(a.id)+'" '+(compAgent()===a.id?'selected':'')+'>'+esc(a.full_name)+(a.id===S.profile.id?' (me)':'')+'</option>').join('')+'</select></label><label class="bob-field bob-comp-search"><span>Find a product</span><input id="bobCompSearch" type="search" value="'+esc(B.compSearch)+'" placeholder="Search carriers, products or age ranges…" maxlength="100"></label><label class="bob-comp-filter"><input id="bobCompOnlySet" type="checkbox" '+(B.compOnlySet?'checked':'')+'>Configured only</label></div><div class="bob-comp-summary"><span><b>'+groups.length+'</b> carriers</span><span><b>'+count+'</b> products</span><span><b id="bobCompConfiguredCount">'+configured+'</b> with saved rates</span><p>Unconfigured products stay blank until you set a rate.</p></div><div id="bobCompResults" class="bob-comp-cards">'+compResults()+'</div></section>';
 }
 function compRateForm(carrier='',product=''){
  if(!S.profile.is_super_admin)return;const user=B.user;
  const initialRates=(B.grid?.rows||[]).filter(r=>r.agent_id===compAgent()&&compKey(r.carrier)===compKey(carrier)&&compKey(r.policy_type)===compKey(product)).sort((a,b)=>String(b.effective_date).localeCompare(String(a.effective_date))),current=initialRates.find(r=>r.effective_date<=localDate());
  openModal('<div class="bob-modal-heading"><div><p class="bob-comp-eyebrow">COMPENSATION</p><h2>Set a product rate</h2><p>Choose the agent, product and effective date.</p></div><button type="button" class="bob-detail-close" id="bobCancelTop" aria-label="Close">×</button></div><form id="bobGridForm"><div class="bob-client-fields"><label class="bob-field"><span>Agent / admin</span><select name="agent" required>'+options(compAgents(),compAgent(),'Choose agent')+'</select></label>'+input('Carrier','carrier','list="bobCompCarriers" value="'+esc(carrier)+'" maxlength="100" autocomplete="off" required')+'<datalist id="bobCompCarriers">'+[...new Set([...carriers,...(B.grid?.rows||[]).map(r=>r.carrier)])].map(c=>'<option value="'+esc(c)+'">').join('')+'</datalist><label class="bob-field bob-full"><span>Product</span><select name="type" required></select></label><label class="bob-field bob-full" id="bobCompCustomWrap" hidden><span>Custom product name</span><input name="customProduct" maxlength="100" placeholder="Use the exact product name recorded on the policy"></label>'+input('Agent comp %','comp','type="number" min="0" max="200" step="0.001" value="'+esc(current?.comp_percent??'')+'" placeholder="Enter rate" required')+input('Advance %','advance','type="number" min="0" max="100" step="0.001" value="'+esc(current?.advance_percent??'')+'" placeholder="Enter advance" required')+input('Effective from','effective','type="date" value="'+localDate()+'" required')+'</div><p class="bob-form-hint" id="bobCompRateHint">A new effective date keeps previous rates in history. Already priced deals keep their saved rates. Match the carrier and product on the policy exactly.</p><div id="bobGridError" role="alert"></div><footer class="bob-modal-footer"><button type="button" class="btn secondary" id="bobCancel">Cancel</button><button class="btn primary" id="bobSaveComp">Save rate</button></footer></form>');
  q('#bobCancel').onclick=q('#bobCancelTop').onclick=closeModal;
  const form=q('#bobGridForm'),custom=()=>{const useCustom=form.elements.type.value==='__custom__';q('#bobCompCustomWrap').hidden=!useCustom;form.elements.customProduct.disabled=!useCustom;form.elements.customProduct.required=useCustom;};
  const populate=(value='')=>{const name=form.elements.carrier.value,known=productCatalog.find(c=>compKey(c.carrier)===compKey(name)),saved=(B.grid?.rows||[]).filter(r=>compKey(r.carrier)===compKey(name)).map(r=>r.policy_type),choices=[...new Set([...(known?.products||[]).map(productName),...saved,...types,value].filter(Boolean))];form.elements.type.innerHTML='<option value="">Choose product</option>'+choices.map(p=>'<option value="'+esc(p)+'" '+(p===value?'selected':'')+'>'+esc(p)+'</option>').join('')+'<option value="__custom__">+ Custom product…</option>';custom();};
  const syncRates=()=>{const type=form.elements.type.value,rate=(B.grid?.rows||[]).filter(r=>r.agent_id===form.elements.agent.value&&compKey(r.carrier)===compKey(form.elements.carrier.value)&&compKey(r.policy_type)===compKey(type)&&r.effective_date<=localDate()).sort((a,b)=>String(b.effective_date).localeCompare(String(a.effective_date)))[0];form.elements.comp.value=rate?.comp_percent??'';form.elements.advance.value=rate?.advance_percent??'';};
  populate(product);form.elements.carrier.onchange=()=>{populate();syncRates();};form.elements.type.onchange=()=>{custom();syncRates();};form.elements.agent.onchange=syncRates;let saving=false;
  form.onsubmit=async e=>{e.preventDefault();if(saving||!valid(user)||!S.profile.is_super_admin||!form.reportValidity())return;const v=Object.fromEntries(new FormData(form)),type=(v.type==='__custom__'?v.customProduct:v.type).trim();if(!type){q('#bobGridError').textContent='Enter a product name.';return;}saving=true;q('#bobSaveComp').disabled=true;
   try{await rpc('book_grid',{p_action:'save',p_agent:v.agent,p_carrier:v.carrier.trim(),p_policy_type:type,p_comp:Number(v.comp),p_advance:Number(v.advance),p_effective:v.effective});if(!valid(user))return;closeModal();B.compAgent=v.agent;await refresh();flash('Rate saved. Unpriced matching deals updated.');}
   catch(x){if(valid(user)&&q('#bobGridError')){q('#bobGridError').textContent=x.message;q('#bobSaveComp').disabled=false;}}finally{saving=false;}
  };
 }
 function resetCompPin(){
  if(!S.profile.is_super_admin)return;const user=B.user,id=compAgent(),name=compAgents().find(a=>a.id===id)?.full_name||'agent';
  openModal('<h2>Reset '+esc(name)+'’s Book PIN?</h2><p>They will set a new personal PIN next time they open their book.</p><div id="bobResetError" role="alert"></div><button class="btn primary" id="bobConfirmReset">Reset PIN</button><button class="btn secondary" id="bobCancel">Cancel</button>');q('#bobCancel').onclick=closeModal;
  q('#bobConfirmReset').onclick=async e=>{if(!valid(user))return;e.target.disabled=true;try{await rpc('book_grid',{p_action:'reset-pin',p_agent:id});if(!valid(user))return;closeModal();await refresh();flash('Book PIN reset.');}catch(x){if(valid(user)&&q('#bobResetError')){q('#bobResetError').textContent=x.message;e.target.disabled=false;}}};
 }
 function bindCompGrid(){
  if(!q('#bobCompResults'))return;
  const actions=()=>qa('[data-comp-carrier]').forEach(button=>button.onclick=()=>compRateForm(button.dataset.compCarrier,button.dataset.compProduct));
  const paint=()=>{q('#bobCompResults').innerHTML=compResults();q('#bobCompConfiguredCount').textContent=compGroups().reduce((n,g)=>n+g.products.filter(p=>p.rates.length).length,0);actions();bindCarrierLogos();};
  q('#bobCompAgent').onchange=e=>{B.compAgent=e.target.value;paint();};q('#bobCompSearch').oninput=e=>{B.compSearch=e.target.value;paint();};q('#bobCompOnlySet').onchange=e=>{B.compOnlySet=e.target.checked;paint();};
  if(q('#bobAddRate'))q('#bobAddRate').onclick=()=>compRateForm();if(q('#bobResetPin'))q('#bobResetPin').onclick=resetCompPin;actions();
 }
 function bind(){
  clearDrag();if(S.tab!=='book-business')return;
  if(q('#bobRetry'))q('#bobRetry').onclick=refresh;
  if(q('#bobBrandRetry'))q('#bobBrandRetry').onclick=refresh;
  qa('[data-bob-brand-image]').forEach(img=>{const fallback=()=>{img.hidden=true;img.nextElementSibling.hidden=false;};img.onerror=fallback;if(img.complete&&!img.naturalWidth)fallback();});
  const f=q('#bobPinForm');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f)),create=!B.access.has_pin,err=q('#bobPinError');if(create&&v.pin!==v.confirm){err.textContent='PINs must match.';return;}f.querySelector('button').disabled=true;try{const a=await rpc('book_access',{p_action:create?'set':'unlock',p_pin:v.pin});f.reset();if(a.error)throw new Error(a.error);await refresh();}catch(e){err.textContent=e.message;f.querySelector('button').disabled=false;}};
  if(!B.access?.unlocked)return;
  bindCarrierLogos();
  qa('[data-bob-tab]').forEach(b=>b.onclick=async()=>{B.tab=b.dataset.bobTab;if(B.tab==='pipeline')B.stage='';B.notice='';B.page=1;B.selectedId=null;B.detail=null;detailRequest++;await refresh();});
  if(q('#bobAgencyLogo'))q('#bobAgencyLogo').onclick=agencyLogoForm;
  q('#bobLock').onclick=async()=>{try{await rpc('book_access',{p_action:'lock'});expire();}catch(e){B.error=e.message;render();}};
  q('#bobChangePin').onclick=()=>{openModal('<h2>Change Book PIN</h2><form id="bobChangeForm" class="stack">'+input('Current PIN','old','type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required')+input('New six-digit PIN','pin','type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required')+input('Confirm new PIN','confirm','type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required')+'<div id="bobChangeError" role="alert"></div><button class="btn primary">Save PIN</button><button type="button" class="btn secondary" id="bobCancel">Cancel</button></form>');q('#bobCancel').onclick=closeModal;q('#bobChangeForm').onsubmit=async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));if(v.pin!==v.confirm){q('#bobChangeError').textContent='PINs must match.';return;}f.querySelector('button').disabled=true;try{const a=await rpc('book_access',{p_action:'change',p_pin:v.pin,p_old_pin:v.old});if(a.error)throw new Error(a.error);closeModal();await refresh();}catch(x){q('#bobChangeError').textContent=x.message;f.querySelector('button').disabled=false;}};};
  q('#bobAddClient').onclick=()=>clientForm();q('#bobExport').onclick=exportCSV;
  if(q('#bobSearch'))q('#bobSearch').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if((v.agent||'')!==B.agent){B.selectedId=null;B.detail=null;detailRequest++;}B.search=v.search;B.agent=v.agent||'';B.stage=v.stage||'';B.carrier=v.carrier||'';B.taskStatus=v.taskStatus||B.taskStatus;B.page=1;await refresh();};
  if(q('#bobSearch [name=agent]'))q('#bobSearch [name=agent]').onchange=()=>q('#bobSearch').requestSubmit();
  if(q('#bobRefresh'))q('#bobRefresh').onclick=refresh;
  if(q('#bobPrev'))q('#bobPrev').onclick=async()=>{B.page=Math.max(1,B.page-1);await refresh();};
  if(q('#bobNext'))q('#bobNext').onclick=async()=>{B.page++;await refresh();};
  if(q('#bobClearFilters'))q('#bobClearFilters').onclick=async()=>{B.stage='';B.search='';B.agent='';B.carrier='';B.page=1;await refresh();};
  qa('[data-bob-filter]').forEach(b=>b.onclick=async()=>{B.stage=B.stage===b.dataset.bobFilter?'':b.dataset.bobFilter;B.page=1;await refresh();});
  qa('[data-bob-view-stage]').forEach(b=>b.onclick=async()=>{B.stage=b.dataset.bobViewStage;B.tab='pipeline';B.pipelineView='list';B.page=1;await refresh();});
  qa('.bob-select-client').forEach(b=>b.onclick=()=>{if(Date.now()>=suppressClickUntil)fetchDetail(b.dataset.id);});
  if(q('#bobCloseDetail'))q('#bobCloseDetail').onclick=()=>{const id=B.selectedId;B.selectedId=null;B.detail=null;detailRequest++;render();qa('.bob-select-client').find(b=>b.dataset.id===id)?.focus({preventScroll:true});};
  if(q('#bobDetailRetry'))q('#bobDetailRetry').onclick=()=>fetchDetail(B.selectedId);
  if(q('#bobAddPolicy'))q('#bobAddPolicy').onclick=()=>policyForm();
  if(q('#bobDeleteClient'))q('#bobDeleteClient').onclick=deleteClientForm;
  if(q('#bobEditContact'))q('#bobEditContact').onclick=contactForm;
  if(q('#bobCompleteContact'))q('#bobCompleteContact').onclick=contactForm;
  qa('[data-bob-carrier-status]').forEach(b=>b.onclick=()=>carrierStatusForm(B.detail.policies.find(p=>p.id===b.dataset.bobCarrierStatus)));
  qa('[data-bob-edit-policy]').forEach(b=>b.onclick=()=>policyForm(B.detail.policies.find(p=>p.id===b.dataset.bobEditPolicy)));
  if(q('#bobAddNote'))q('#bobAddNote').onclick=()=>activityForm('note');
  if(q('#bobAddTask'))q('#bobAddTask').onclick=()=>activityForm('task');
  qa('[data-bob-move]').forEach(e=>e.onchange=()=>moveClient(e.dataset.bobMove,e.value));
  qa('[data-bob-task]').forEach(b=>b.onclick=()=>toggleTask(b));
  qa('[data-bob-move]').forEach(e=>e.disabled=B.busy);
  qa('[data-bob-display]').forEach(b=>b.onclick=async()=>{B.pipelineView=b.dataset.bobDisplay;B.page=1;B.stage='';await refresh();});
  if(B.tab==='pipeline')qa('#bobSearch select').forEach(e=>e.onchange=()=>q('#bobSearch').requestSubmit());
  bindDrag();
  bindCompGrid();
 }
